-- Insert Quiz Questions for Lesson: What Calendars Do Inside LeadProspectrr

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 6 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 6 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'what-calendars-do' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson what-calendars-do not found in module 6';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the main purpose of a booking calendar in LeadProspectrr?', 
    '["To replace your existing calendar app","To let someone choose an appointment time from times you make available","To send unlimited emails to prospects","To block all incoming calls"]'::jsonb,
    'To let someone choose an appointment time from times you make available',
    'A booking calendar lets prospects and clients choose appointment times from your available slots, eliminating back-and-forth scheduling messages.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What happens automatically when someone books through your link?', 
    '["Nothing happens until you manually confirm","LeadProspectrr records the appointment and can send confirmations and reminders","They are immediately charged a fee","Your calendar is deleted"]'::jsonb,
    'LeadProspectrr records the appointment and can send confirmations and reminders',
    'LeadProspectrr automatically records the appointment and can send confirmation emails and reminder messages before the meeting.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why is a booking link better than email scheduling?', 
