-- Insert Quiz Questions for Lesson: Key Calendar Terms Made Simple

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 6 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 6 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'key-calendar-terms' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson key-calendar-terms not found in module 6';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is ''availability'' in calendar terms?', 
    '["Your entire calendar schedule","The days and times people are allowed to book","The number of appointments you can handle","Your business hours only"]'::jsonb,
    'The days and times people are allowed to book',
    'Availability refers to the specific days and times you make available for people to book appointments.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the purpose of ''buffer time''?', 
    '["To make appointments longer","To create space before or after appointments for prep, notes, or travel","To block all bookings","To send more reminders"]'::jsonb,
    'To create space before or after appointments for prep, notes, or travel',
    'Buffer time creates breathing room between appointments so you have time to prepare, take notes, or travel to your next meeting.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What does a ''conflict calendar'' do?', 
    '["Creates more appointments","Blocks unavailable times to prevent double-booking","Sends marketing emails","Deletes old appointments"]'::jsonb,
    'Blocks unavailable times to prevent double-booking',
    'A conflict calendar shows LeadProspectrr when you are already busy, blocking those times from being booked to prevent double-booking.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


