-- Insert Quiz Questions for Lesson: Set Up a Basic Calendar

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 6 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 6 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'setup-basic-calendar' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson setup-basic-calendar not found in module 6';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What makes a good calendar name?', 
    '["Calendar 1","30-Minute Discovery Call","Test","New Calendar"]'::jsonb,
    '30-Minute Discovery Call',
    'Good calendar names are clear and descriptive, like ''30-Minute Discovery Call'' or ''Client Check-In'', so prospects understand what they are booking.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'How long should a discovery call typically be?', 
    '["5 minutes","30 minutes","2 hours","All day"]'::jsonb,
    '30 minutes',
    'A standard discovery call is typically 30 minutes—long enough to understand needs but short enough to respect everyone''s time.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you check before saving your calendar?', 
    '["Only the name","Name, length, availability, location, reminders, timezone, and booking link","Nothing, just save it","Only the color scheme"]'::jsonb,
    'Name, length, availability, location, reminders, timezone, and booking link',
    'Before saving, review all settings: name, appointment length, availability, meeting location, reminders, timezone, and booking link to ensure everything is correct.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


