-- Insert Quiz Questions for Lesson: Where to Use the Booking Link

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 6 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 6 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'where-to-use-booking-link' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson where-to-use-booking-link not found in module 6';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Where is a good place to share your booking link?', 
    '["Only on your personal Facebook page","Email signature, website, follow-up messages, thank-you pages","Nowhere, keep it secret","Only in text messages"]'::jsonb,
    'Email signature, website, follow-up messages, thank-you pages',
    'Share your booking link wherever prospects are likely to take action: email signature, website buttons, follow-up messages, thank-you pages, and social media profiles.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should your booking message include?', 
    '["Just the link","Clear instructions about what happens after they book","Your life story","A sales pitch only"]'::jsonb,
    'Clear instructions about what happens after they book',
    'A good booking message includes the link and clear instructions about what happens after booking, like ''Once you book, you will receive the appointment details by email.''', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why put the booking link on your website?', 
    '["To make the website look busy","So interested visitors can immediately take action while their interest is high","To confuse visitors","It is required by law"]'::jsonb,
    'So interested visitors can immediately take action while their interest is high',
    'Adding a booking link to your website lets interested visitors book immediately while their interest is high, converting website traffic into actual appointments.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


